-- Tenant isolation: list-partition by tenant so no approximate index is shared.
CREATE TABLE tenant_chunks (
  tenant_id  int          NOT NULL,
  chunk_id   bigint       NOT NULL,
  embedding  vector(1536) NOT NULL
) PARTITION BY LIST (tenant_id);
-- ...then create one partition per tenant and an HNSW index on each.

-- A filtered query on a shared, HNSW-indexed table: the WHERE clause runs
-- after the index scan, so enable an iterative scan to keep the LIMIT satisfied.
BEGIN;
SET LOCAL hnsw.iterative_scan = strict_order;
SELECT chunk_id
  FROM chunks
 WHERE category_id = $2
 ORDER BY embedding <=> $1
 LIMIT 10;
COMMIT;
